          [{ method: 'PATCH', path: 'content_pieces?id=eq.' + p.id + '&status=eq.in_review', body: { status: 'scheduled', ghl_status: 'scheduled', ghl_approval_status: 'approved', scheduled_at: post3.scheduleDate, updated_at: nowIso } }]);
